@login_required
def trigger_partner_commission_reconciliation(request):
    partner_id = request.GET.get('partner_id')
    if not request.user.affiliate_partners.filter(id=partner_id).exists():
        raise PermissionDenied("Unauthorized partner ID.")
    call_command('reconcile_partner_commissions', partner_id=partner_id)
    return JsonResponse({'status': 'reconciliation queued', 'partner_id': partner_id})
